const email = $input.first().json;

const de = email.from || '';
const nombre = de.includes('<') ? de.split('<')[0].trim() : de.split('@')[0];
const asunto = (email.subject || '').toLowerCase();
const cuerpoRaw = email.text || email.html || email.snippet || '';
const cuerpo = cuerpoRaw.toLowerCase();

// Detectar si parece un pedido
const esPedido = asunto.match(/pedido|compra|quiero|pedir|encargar|encargo|solicitud|order/) ||
                  cuerpo.match(/quiero|quisiera|necesito|pedido|pedir|comprar|encargar|cantidad|unidades|unidad/);

if (!esPedido) {
  return [{ json: { es_pedido: false, de, asunto, nombre } }];
}

// Extraer artículos
const lineas = cuerpoRaw.split(/\n|,|;/);
const items = [];

for (const linea of lineas) {
  const l = linea.trim();
  if (!l) continue;
  const m1 = l.match(/(\d+)\s*(?:unidades?|uds?|x|de)\s+(.+)/i);
  if (m1) { items.push({ nombre: m1[2].trim(), cantidad: parseInt(m1[1]), precio: 0 }); continue; }
  const m2 = l.match(/(.+?)\s*\(?[xX](\d+)\)?/);
  if (m2) { items.push({ nombre: m2[1].trim(), cantidad: parseInt(m2[2]), precio: 0 }); continue; }
  if (l.match(/portavela|vela|jabon|difusor|cesta|caja|pack|set|kit|figura|decoracion|adorno/i)) {
    items.push({ nombre: l.replace(/[-•*]/g, '').trim(), cantidad: 1, precio: 0 });
  }
}

if (items.length === 0) {
  items.push({ nombre: email.subject || 'Ver correo', cantidad: 1, precio: 0 });
}

const telefonoMatch = cuerpoRaw.match(/(?:\+34|0034)?\s*[6789]\d{8}/);
const telefono = telefonoMatch ? telefonoMatch[0].replace(/\s/g, '') : '';
const numero_pedido = 'EMAIL-' + Date.now();

return [{ json: {
  es_pedido: true,
  numero_pedido,
  nombre_cliente: nombre,
  email_cliente: de,
  telefono,
  asunto: email.subject || '',
  items_json: JSON.stringify(items),
  notas: 'Correo: ' + (email.subject || '') + ' | De: ' + de + ' | ' + cuerpoRaw.substring(0, 300),
  fecha_pedido: new Date().toISOString().slice(0, 19).replace('T', ' ')
}}];
